    return {1: 31, 2: isLeap(year), 3: 31, 4: 30, 5: 31, 6: 30,
            7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}


def no_of_days_remaining(mon, year):
    days = 0
    md = _month_days(year)
    if 1 <= mon <= 12:
        for m in range(mon, 13):
            days += md[m]
    return days


def no_of_days_passed(mon, year):
    days = 0
    md = _month_days(year)
    if 1 <= mon <= 12:
        for m in range(mon, 0, -1):
            days += md[m]
